CREATE TABLE network_commission_settings(id INTEGER PRIMARY KEY CHECK(id=1),data JSONB NOT NULL,version INTEGER NOT NULL DEFAULT 1);
INSERT INTO network_commission_settings(id,data) VALUES(1,'{"stepEnabled":false,"affiliateEnabled":false,"basis":"bv","bvPointValue":1,"steps":[{"rate":0}],"affiliateRate":0,"upline":"binary_parent","affiliateMode":"original_step_income"}');
CREATE TABLE network_commission_contexts(order_id BIGINT PRIMARY KEY REFERENCES records(id),buyer_id BIGINT NOT NULL REFERENCES records(id),snapshot JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE network_commission_orders(order_id BIGINT PRIMARY KEY REFERENCES network_commission_contexts(order_id),status TEXT NOT NULL CHECK(status IN ('Paid','Skipped')),reason TEXT NOT NULL DEFAULT '',snapshot JSONB NOT NULL,step_total NUMERIC(20,2) NOT NULL DEFAULT 0,affiliate_total NUMERIC(20,2) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE network_commission_entries(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES network_commission_orders(order_id),user_id BIGINT NOT NULL REFERENCES records(id),source_user_id BIGINT NOT NULL REFERENCES records(id),kind TEXT NOT NULL CHECK(kind IN ('Step','Affiliate')),level INTEGER NOT NULL CHECK(level>0),source_level INTEGER NOT NULL CHECK(source_level>0),rate NUMERIC(6,2) NOT NULL CHECK(rate>0 AND rate<=100),base_amount NUMERIC(20,2) NOT NULL CHECK(base_amount>0),amount NUMERIC(20,2) NOT NULL CHECK(amount>0),ledger_id BIGINT NOT NULL UNIQUE REFERENCES member_ledger(id),source_entry_id BIGINT REFERENCES network_commission_entries(id) DEFERRABLE INITIALLY DEFERRED,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(order_id,kind,source_user_id,user_id,level));
CREATE INDEX network_commission_entries_member ON network_commission_entries(user_id,id DESC);
CREATE TRIGGER network_commission_context_immutable BEFORE UPDATE OR DELETE ON network_commission_contexts FOR EACH ROW EXECUTE FUNCTION protect_member_ledger();
CREATE TRIGGER network_commission_order_immutable BEFORE UPDATE OR DELETE ON network_commission_orders FOR EACH ROW EXECUTE FUNCTION protect_member_ledger();
CREATE TRIGGER network_commission_entry_immutable BEFORE UPDATE OR DELETE ON network_commission_entries FOR EACH ROW EXECUTE FUNCTION protect_member_ledger();
